package com.tencent.weknora.model.client;
import com.fasterxml.jackson.databind.*;import java.nio.file.*;import java.util.*;
final class OllamaTypedBinderParityTest {
 @org.junit.jupiter.api.Test void actualLockedGoSDKTypedFieldsAndCustomUnmarshal()throws Exception{int failures=0,count=0;JsonNode cases=OllamaJson.JSON.readTree(Files.readString(Path.of(System.getProperty("weknora.ollama.binder.fixture","src/test/java/com/tencent/weknora/model/client/go-ollama-binder.json"))));for(JsonNode c:cases){String source=c.path("source").asText();OllamaTypedJson.Schema kind=OllamaTypedJson.Schema.valueOf(c.path("kind").asText().toUpperCase(Locale.ROOT));String error="";JsonNode actual=null;try{actual=OllamaTypedJson.bind(source,kind);}catch(Exception ex){error=ex.getMessage();}if(!error.equals(c.path("error").asText())){if(failures++<60)System.out.println(kind+" "+source+"\n EXPECT: "+c.path("error").asText()+"\n ACTUAL: "+error);}else if(error.isEmpty()){JsonNode expected=OllamaTypedJson.bind(c.path("result").toString(),kind);if(!same(expected,actual)){if(failures++<60)System.out.println(kind+" "+source+"\n EXPECT: "+expected+"\n ACTUAL: "+actual);}}if(error.isEmpty()&&c.has("arguments")){int index=0;for(JsonNode tool:actual.path("message").path("tool_calls")){String argsJSON=OllamaJson.arguments(tool.path("function").path("arguments"));if(!argsJSON.equals(c.path("arguments").get(index++).asText())){failures++;System.out.println("ARGUMENTS "+source+" EXPECT "+c.path("arguments")+" ACTUAL "+argsJSON);}}}if(error.isEmpty()&&c.has("bits")){JsonNode vectors=actual.path("embeddings");for(int r=0;r<vectors.size();r++)for(int column=0;column<vectors.get(r).size();column++)if(Float.floatToRawIntBits(vectors.get(r).get(column).floatValue())!=(int)c.path("bits").get(r).get(column).asLong()){failures++;System.out.println("FLOAT BITS "+source);}}count++;}System.out.println(count+" cases / "+failures+" failures");org.assertj.core.api.Assertions.assertThat(count).isEqualTo(1498);org.assertj.core.api.Assertions.assertThat(failures).isZero();}
 static boolean same(JsonNode a,JsonNode b){if(a.isNumber()&&b.isNumber())return a.asDouble()==b.asDouble();if(a.isObject()&&b.isObject()){for(Iterator<String> it=a.fieldNames();it.hasNext();){String k=it.next();JsonNode x=a.get(k),y=b.get(k);if(y==null)return false;if(Set.of("logprobs","images","tool_calls","bytes","top_logprobs").contains(k)&&(x.isNull()||x.isArray()&&x.isEmpty())&&(y.isNull()||y.isArray()&&y.isEmpty()))continue;if(!same(x,y))return false;}return a.size()==b.size();}if(a.isArray()&&b.isArray()){if(a.size()!=b.size())return false;for(int i=0;i<a.size();i++)if(!same(a.get(i),b.get(i)))return false;return true;}return a.equals(b);}
}
